import{_ as r,l as n,o as e,c as s,v as t,p as i,x as l,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"AVL 与旋转","description":"","frontmatter":{"title":"AVL 与旋转","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/avl-rotate.md","filePath":"cs/avl-rotate.md","lastUpdated":1789023840000}'),c={name:"cs/avl-rotate.md"};function A(_,a,T,E,m,B){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="avl-与旋转" tabindex="-1">AVL 与旋转 <a class="header-anchor" href="#avl-与旋转" aria-label="Permalink to &quot;AVL 与旋转&quot;">​</a></h1><div class="epigraph"><p>左右子树高度差不超过 1，插入后用一次或两次旋转恢复；高度就被钉在对数。</p><footer>—— 据 Adelson-Velsky and Landis, An Algorithm for the Organization of Information, 1962 整理</footer></div><p><a href="/cs/bst-delete">上一课</a>的查找是 \\(\\Theta(h)\\)，并承认插入可以把树拉成链。<a href="/cs/tree-as-acyclic">树作为无环连通图</a>的高度可以是 \\(n-1\\)。本课不重讲 BST 不变式。缺口是：插入删除之后仍要 BST，同时 \\(|h_L-h_R|\\le 1\\) 在每个节点成立。手段是旋转：改几根指针，中序序列不变。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BST 合同若写成最坏 \\(\\Theta(\\log n)\\)，必须限制高度。完全二叉树有该高度，但插入不能每次重建。缺口不是换散列，而是<strong>局部改指针的旋转</strong>：左旋、右旋把子树「拧」一格，保持中序，改变高度差。</p><p>AVL 规定平衡因子在 \\(\\{-1,0,1\\}\\)。插入沿路径回退，遇到失衡则单旋或双旋。删除同样回退，可能连续旋转。本课把旋转钉清楚，不把所有删除情形画成百科。</p><p><span class="marginnote">旋转是树的结合律操作：\\((AB)C\\) 对 \\(A(BC)\\)，键序不变。后课红黑树用同一对旋转。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>右旋：节点 \\(y\\) 的左孩子 \\(x\\) 升为根，\\(x\\) 的右子树接到 \\(y\\) 的左。左旋对称。BST 不变式保持，因为 \\(x\\) 与 \\(y\\) 之间没有别的键。</p><p>插入失衡的四种形状：LL 右旋，RR 左旋，LR 先左后右，RL 先右后左。每次插入 \\(O(1)\\) 次旋转，整次插入仍 \\(\\Theta(\\log n)\\)，因路径长 \\(O(\\log n)\\)。</p>',10)),(e(),i(p,null,{default:l(()=>[h(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22BST%20%E6%8F%92%E5%85%A5%22%5D%20--%3E%20CHK%5B%22%E5%9B%9E%E9%80%80%E7%9C%8B%E5%B9%B3%E8%A1%A1%E5%9B%A0%E5%AD%90%22%5D%0A%20%20CHK%20--%3E%7C%22%7C%E5%B7%AE%7C%E2%89%A41%22%7C%20OK%5B%22%E7%BB%93%E6%9D%9F%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%A4%B1%E8%A1%A1%22%7C%20ROT%5B%22%E5%8D%95%E6%97%8B%E6%88%96%E5%8F%8C%E6%97%8B%22%5D%0A%20%20ROT%20--%3E%20OK%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>AVL 高度 \\(h\\le c\\log n\\)，最坏查找/插入/删除都 \\(\\Theta(\\log n)\\)。比后课红黑更严，因而可能更多旋转，树更扁，查找略快、插入略慢——这是常数层，合同同为对数。</p><p>旋转改 \\(O(1)\\) 条指针，不搬键。与数组插入的 \\(\\Theta(n)\\) 搬移对比，这是树作为字典表示的理由。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入红黑的颜色约束，不把 AVL 写成唯一平衡方案。也不处理并发 AVL。父指针便于回退；用栈沿路径也可以。</p><p>后课默认：平衡 BST 存在，旋转是公共原语。红黑用更松的约束换插入时旋转次数的更稳上界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AVL：每节点左右高度差 \\(\\le 1\\)，高度 \\(\\Theta(\\log n)\\)。</li><li>旋转保持中序与 BST，用来恢复平衡。</li><li>红黑树用颜色代替严格高度差，下一课只给直觉。</li><li>出处：Adelson-Velsky and Landis, 1962；Cormen et al. 旋转作为预备。</li></ul>',8))])}const C=r(c,[["render",A]]);export{u as __pageData,C as default};
